steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(identifier: \"WEB-12\") { id identifier title url } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { identifier: { eq: \"WEB-12\" } }) { nodes { id identifier title url } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { teams { nodes { id name key } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { team: { id: { eq: \"t-web\" } }, number: { eq: 12 } }) { nodes { id identifier title url } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { comments(filter: { issue: { id: { eq: \"i-12\" } } }) { nodes { id body user { id name } createdAt } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issue(id: \"i-12\") { id identifier title comments { nodes { id body user { id name } createdAt } } } }"
  }'
